// src/tools/public-apis/catalog.mjs
// Loads the curated public-apis catalog and provides offline search/lookup.
// The catalog is generated by scripts/build-public-apis.mjs.
import fs from "node:fs";
import { fileURLToPath } from "node:url";

const CATALOG_PATH = new URL("./catalog.json", import.meta.url);

function load() {
  const raw = JSON.parse(fs.readFileSync(fileURLToPath(CATALOG_PATH), "utf8"));
  const entries = Array.isArray(raw.entries) ? raw.entries : [];
  const byId = new Map();
  const byHost = new Map();
  for (const entry of entries) {
    byId.set(entry.id, entry);
    if (!byHost.has(entry.host)) byHost.set(entry.host, entry);
  }
  return { raw, entries, byId, byHost };
}

const data = load();

export const catalogSize = data.entries.length;
export const catalogCategories = data.raw.categories || [];
export const catalogSource = data.raw.source || "";
export const catalogGeneratedAt = data.raw.generated_at || null;

/** Hostnames declared by the catalog. Used to allow curated outbound calls. */
export function catalogHosts() {
  return new Set(data.byHost.keys());
}

export function getById(id) {
  return data.byId.get(String(id || "").toLowerCase()) || null;
}

export function getByHost(host) {
  return data.byHost.get(String(host || "").toLowerCase()) || null;
}

/**
 * Offline search over the catalog. All filters are optional and ANDed.
 * @param {{query?:string, category?:string, auth?:string, httpsOnly?:boolean, limit?:number, offset?:number}} opts
 */
export function search({ query = "", category = "", auth = "", httpsOnly = false, limit = 20, offset = 0 } = {}) {
  const q = String(query || "").trim().toLowerCase();
  const cat = String(category || "").trim().toLowerCase();
  const authFilter = String(auth || "").trim().toLowerCase();
  const terms = q ? q.split(/\s+/).filter(Boolean) : [];

  const matched = data.entries.filter((e) => {
    if (cat && e.category.toLowerCase() !== cat) return false;
    if (authFilter && e.auth.toLowerCase() !== authFilter) return false;
    if (httpsOnly && !e.https) return false;
    if (terms.length) {
      const haystack = `${e.name} ${e.description} ${e.category} ${e.host}`.toLowerCase();
      if (!terms.every((t) => haystack.includes(t))) return false;
    }
    return true;
  });

  const capped = Math.max(1, Math.min(100, Number(limit) || 20));
  const start = Math.max(0, Number(offset) || 0);
  return {
    total: matched.length,
    count: matched.slice(start, start + capped).length,
    offset: start,
    results: matched.slice(start, start + capped)
  };
}

export function stats() {
  const byCategory = {};
  const byAuth = {};
  let https = 0;
  for (const e of data.entries) {
    byCategory[e.category] = (byCategory[e.category] || 0) + 1;
    byAuth[e.auth] = (byAuth[e.auth] || 0) + 1;
    if (e.https) https += 1;
  }
  return {
    count: data.entries.length,
    categories: Object.keys(byCategory).length,
    https: https,
    https_only: data.entries.length - https,
    by_category: byCategory,
    by_auth: byAuth,
    source: catalogSource,
    generated_at: catalogGeneratedAt
  };
}
